objs=load()
def find(src, reg=None, sub=None, part=None):
    r=[]
    for o in objs:
        if o['_src']!=src: continue
        if sub and sub not in o['file']: continue
        if part is not None:
            its=[i for i in o['items'] if part(i.get('part',''))]
        else: its=o['items']
        r.append((o,its))
    return r
def col(label, src, sub=None, part=None):
    m=find(src,sub=sub,part=part)
    assert len(m)>=1,(label,src,sub)
    o,its=m[0]
    return dict(label=label,obj=o,items=its,file=o['file'])
